import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"术语表","description":"Hearth 常用产品与工程概念的统一解释。","frontmatter":{"title":"术语表","description":"Hearth 常用产品与工程概念的统一解释。","outline":false},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":1793706118000}'),s={name:"reference/glossary.md"};function o(n,t,l,_,c,i){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p class="lead">同一个词在文档、界面和代码里应当表达同一件事。这里解释 Hearth 最常用的概念，优先使用用户能理解的说法。</p><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>Hearth</td><td>单用户、自托管、长期运行的个人 Agent OS</td></tr><tr><td>任务</td><td>用户希望完成、可以验收和恢复的工作项</td></tr><tr><td>工作单元</td><td>任务中被授权、可单独执行和验证的一小段工作</td></tr><tr><td>执行记录</td><td>某一次真实执行留下的输入、结果、产物和失败原因</td></tr><tr><td>事实记录</td><td>只追加的系统记录；界面、统计和通知都从它重建</td></tr><tr><td>检查点</td><td>长任务中途保存的可恢复状态</td></tr><tr><td>快照</td><td>某一时刻的工作区或数据副本，用于恢复和比较</td></tr><tr><td>执行器</td><td>完成某类工作的受控能力，例如通用推理、Codex、浏览器或桌面操作</td></tr><tr><td>连接器</td><td>通过官方接口连接邮件、日历、云盘等外部系统</td></tr><tr><td>授权范围</td><td>用户允许某类动作在什么对象、时间和风险范围内发生</td></tr><tr><td>审批</td><td>用户针对一次具体外部动作作出的确认</td></tr><tr><td>外部副作用</td><td>发送、写入、删除、发布、付款、设备操作等真实世界影响</td></tr><tr><td>回执</td><td>外部动作发生后的可核对结果</td></tr><tr><td>对账</td><td>在结果不确定时查询外部状态，确认动作是否真的发生</td></tr><tr><td>产物</td><td>任务交付的文件、报告、表格、链接或其他结果</td></tr><tr><td>记忆</td><td>带来源、适用范围和敏感度的长期或中期背景</td></tr><tr><td>方法</td><td>经过验证、可以重复使用的工作流程或工具配方</td></tr><tr><td>评估</td><td>用真实任务、基线、验证器和成本指标判断能力</td></tr><tr><td>灰度</td><td>让新方法先在小范围真实使用，再决定是否扩大</td></tr><tr><td>停止开关</td><td>在异常时暂停任务、设备或全部外部动作的入口</td></tr><tr><td>验证通过</td><td>有产物、证据和必要回执支持的真实完成</td></tr></tbody></table>',3)])])}const f=d(s,[["render",o]]);export{p as __pageData,f as default};
